css:
@page {
    size: A4;
    margin: 15mm;
}

.print-container {
    width: 100%;
    border-collapse: collapse;
}

thead {
    display: table-header-group;
}

tfoot {
    display: table-footer-group;
}

.header-space {
    height: 10px;
}

.footer-space {
    height: 90px;
}

.footer {
    position: fixed;
    bottom: 0;
    left: 0;
    right: 0;

    height: 60px;
    background: white;

    border-top: 1px solid #ccc;
    z-index: 9999;
}

.footer-content {
    display: flex;
    justify-content: space-between;
    align-items: center;

    height: 60px;
    padding: 0 15px;
}

.footer img {
    height: 50px;
    width: auto;
}
.section-title {
    page-break-before: always;
}
